import React, {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';

import {
  FiEye,
  FiTrash2,
  FiSearch,
  FiRefreshCw,
  FiX,
  FiUsers,
  FiMail,
  FiPhone,
  FiBookOpen,
  FiCalendar,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


// ==========================================
// STATUS OPTIONS
// ==========================================

const STATUS_OPTIONS = [
  'pending',
  'approved',
  'rejected',
  'completed',
];


// ==========================================
// STATUS STYLE
// ==========================================

const getStatusStyle = (status) => {
  switch (
    String(status || '')
      .toLowerCase()
      .trim()
  ) {
    case 'approved':
      return 'bg-[#EBF9F0] text-[#2E7D32]';

    case 'rejected':
      return 'bg-[#FFEBEE] text-[#C62828]';

    case 'completed':
      return 'bg-[#F0F7FF] text-[#0D1B3E]';

    case 'pending':
    default:
      return 'bg-[#FFF3E0] text-[#E65100]';
  }
};


// ==========================================
// FORMAT DATE
// ==========================================

const formatDate = (
  date,
  language
) => {
  if (!date) {
    return '-';
  }

  const parsedDate =
    new Date(date);

  if (
    Number.isNaN(
      parsedDate.getTime()
    )
  ) {
    return '-';
  }

  try {
    return parsedDate.toLocaleString(
      language === 'km' ||
      language === 'kh'
        ? 'km-KH'
        : 'en-GB',
      {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      }
    );
  } catch (error) {
    return parsedDate.toLocaleString();
  }
};


// ==========================================
// ADMIN ENROLLMENTS
// ==========================================

const AdminEnrollments = () => {

  // ========================================
  // LANGUAGE
  // ========================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  // ========================================
  // TRANSLATION FALLBACK
  // ========================================

  const tr = (
    key,
    englishFallback,
    khmerFallback
  ) => {
    const translated =
      t(key);

    if (
      translated &&
      translated !== key
    ) {
      return translated;
    }

    return isKhmer
      ? khmerFallback
      : englishFallback;
  };


  // ========================================
  // STATES
  // ========================================

  const [
    enrollments,
    setEnrollments,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    error,
    setError,
  ] = useState('');


  const [
    search,
    setSearch,
  ] = useState('');


  const [
    selectedEnrollment,
    setSelectedEnrollment,
  ] = useState(null);


  const [
    deletingId,
    setDeletingId,
  ] = useState(null);


  const [
    updatingId,
    setUpdatingId,
  ] = useState(null);


  // ========================================
  // GET STATUS LABEL
  // ========================================

  const getStatusLabel = (
    status
  ) => {
    const safeStatus =
      String(
        status || 'pending'
      )
        .toLowerCase()
        .trim();

    const allowedStatus =
      STATUS_OPTIONS.includes(
        safeStatus
      )
        ? safeStatus
        : 'pending';


    const fallbackLabels = {
      pending: {
        en: 'Pending',
        km: 'កំពុងរង់ចាំ',
      },

      approved: {
        en: 'Approved',
        km: 'បានអនុម័ត',
      },

      rejected: {
        en: 'Rejected',
        km: 'បានបដិសេធ',
      },

      completed: {
        en: 'Completed',
        km: 'បានបញ្ចប់',
      },
    };


    return tr(
      `enrollments.statuses.${allowedStatus}`,
      fallbackLabels[allowedStatus].en,
      fallbackLabels[allowedStatus].km
    );
  };


  // ========================================
  // GET COURSE NAME
  // ========================================

  const getCourseName = (
    enrollment
  ) => {
    const course =
      enrollment?.course;


    const fallbackCourse =
      `${tr(
        'enrollments.course',
        'Course',
        'វគ្គសិក្សា'
      )} #${
        enrollment?.course_id ||
        '-'
      }`;


    if (!course) {
      return fallbackCourse;
    }


    if (isKhmer) {
      return (
        course.title_km ||
        course.title_en ||
        course.title ||
        fallbackCourse
      );
    }


    return (
      course.title_en ||
      course.title_km ||
      course.title ||
      fallbackCourse
    );
  };


  // ========================================
  // FETCH ENROLLMENTS
  // ========================================

  const fetchEnrollments =
    useCallback(
      async () => {
        try {
          setLoading(true);

          setError('');


          const response =
            await api.get(
              '/api/enrollments/'
            );


          const data =
            response.data;


          if (
            Array.isArray(data)
          ) {
            setEnrollments(
              data
            );
          } else if (
            Array.isArray(
              data?.items
            )
          ) {
            setEnrollments(
              data.items
            );
          } else {
            setEnrollments(
              []
            );
          }

        } catch (err) {
          console.error(
            'Fetch enrollments error:',
            err
          );


          setError(
            getApiErrorMessage(
              err,
              isKhmer
                ? 'មិនអាចទាញយកទិន្នន័យការចុះឈ្មោះបានទេ។'
                : 'Failed to load enrollments.'
            )
          );

        } finally {
          setLoading(false);
        }
      },
      [isKhmer]
    );


  // ========================================
  // LOAD DATA
  // ========================================

  useEffect(() => {
    fetchEnrollments();
  }, [fetchEnrollments]);


  // ========================================
  // FILTER / SEARCH
  // ========================================

  const filteredEnrollments =
    useMemo(() => {
      const keyword =
        search
          .toLowerCase()
          .trim();


      if (!keyword) {
        return enrollments;
      }


      return enrollments.filter(
        (item) => {
          const values = [
            item.id,

            item.khmer_name,

            item.english_name,

            item.gender,

            item.age,

            item.date_of_birth,

            item.nationality,

            item.nation,

            item.religion,

            item.state_id_no,

            item.house_no,

            item.village,

            item.commune_sangkat,

            item.district_khan,

            item.province_city,

            item.email,

            item.phone,

            item.status,

            item.course_id,

            item.course?.title,

            item.course?.title_en,

            item.course?.title_km,

            getCourseName(item),
          ];


          return values.some(
            (value) =>
              String(
                value || ''
              )
                .toLowerCase()
                .includes(
                  keyword
                )
          );
        }
      );
    }, [
      enrollments,
      search,
      language,
    ]);


  // ========================================
  // STATUS COUNTS
  // ========================================

  const totalCount =
    enrollments.length;


  const pendingCount =
    enrollments.filter(
      (item) =>
        String(
          item.status ||
          'pending'
        )
          .toLowerCase()
          .trim() ===
        'pending'
    ).length;


  const approvedCount =
    enrollments.filter(
      (item) =>
        String(
          item.status || ''
        )
          .toLowerCase()
          .trim() ===
        'approved'
    ).length;


  const completedCount =
    enrollments.filter(
      (item) =>
        String(
          item.status || ''
        )
          .toLowerCase()
          .trim() ===
        'completed'
    ).length;


  // ========================================
  // UPDATE STATUS
  // ========================================

  const handleStatusChange =
    async (
      enrollment,
      newStatus
    ) => {
      const oldStatus =
        String(
          enrollment.status ||
          'pending'
        )
          .toLowerCase()
          .trim();


      if (
        oldStatus ===
        newStatus
      ) {
        return;
      }


      try {
        setUpdatingId(
          enrollment.id
        );

        setError('');


        const response =
          await api.patch(
            `/api/enrollments/${enrollment.id}/status`,
            {
              status:
                newStatus,
            }
          );


        const updatedEnrollment =
          response.data;


        setEnrollments(
          (current) =>
            current.map(
              (item) =>
                item.id ===
                  enrollment.id
                  ? {
                      ...item,
                      ...updatedEnrollment,

                      status:
                        updatedEnrollment
                          ?.status ||
                        newStatus,
                    }
                  : item
            )
        );


        setSelectedEnrollment(
          (current) => {
            if (
              !current ||
              current.id !==
                enrollment.id
            ) {
              return current;
            }


            return {
              ...current,
              ...updatedEnrollment,

              status:
                updatedEnrollment
                  ?.status ||
                newStatus,
            };
          }
        );

      } catch (err) {
        console.error(
          'Update status error:',
          err
        );


        setError(
          getApiErrorMessage(
            err,
            isKhmer
              ? 'មិនអាចកែប្រែស្ថានភាពបានទេ។'
              : 'Failed to update enrollment status.'
          )
        );

      } finally {
        setUpdatingId(
          null
        );
      }
    };


  // ========================================
  // DELETE ENROLLMENT
  // ========================================

  const handleDelete =
    async (
      enrollment
    ) => {
      const studentName =
        enrollment.khmer_name ||
        enrollment.english_name ||
        tr(
          'enrollments.student',
          'Student',
          'សិស្ស'
        );


      const confirmed =
        window.confirm(
          isKhmer
            ? `តើអ្នកប្រាកដថាចង់លុបការចុះឈ្មោះរបស់ "${studentName}" មែនទេ?`
            : `Are you sure you want to delete the enrollment for "${studentName}"?`
        );


      if (!confirmed) {
        return;
      }


      try {
        setDeletingId(
          enrollment.id
        );

        setError('');


        await api.delete(
          `/api/enrollments/${enrollment.id}`
        );


        setEnrollments(
          (current) =>
            current.filter(
              (item) =>
                item.id !==
                enrollment.id
            )
        );


        if (
          selectedEnrollment?.id ===
          enrollment.id
        ) {
          setSelectedEnrollment(
            null
          );
        }

      } catch (err) {
        console.error(
          'Delete enrollment error:',
          err
        );


        setError(
          getApiErrorMessage(
            err,
            isKhmer
              ? 'មិនអាចលុបការចុះឈ្មោះបានទេ។'
              : 'Failed to delete enrollment.'
          )
        );

      } finally {
        setDeletingId(
          null
        );
      }
    };


  // ========================================
  // LOADING
  // ========================================

  if (loading) {
    return (
      <div
        className={`
          min-h-[400px]

          flex
          items-center
          justify-center

          ${
            isKhmer
              ? 'font-khmer'
              : 'font-english'
          }
        `}
      >
        <div
          className="
            text-center
          "
        >
          <div
            className="
              w-12
              h-12

              mx-auto

              rounded-full

              border-4
              border-[#F0F7FF]
              border-t-[#0D1B3E]

              animate-spin
            "
          />

          <p
            className="
              mt-4

              text-gray-500
              font-medium
            "
          >
            {tr(
              'enrollments.loading',
              'Loading enrollments...',
              'កំពុងទាញយកការចុះឈ្មោះ...'
            )}
          </p>
        </div>
      </div>
    );
  }


  // ========================================
  // MAIN
  // ========================================

  return (
    <div
      className={`
        w-full
        min-h-screen
        p-6
        bg-[#F0F7FF]

        ${
          isKhmer
            ? 'font-khmer'
            : 'font-english'
        }
      `}
    >

      {/* ==================================
          PAGE HEADER
      ================================== */}

      <div
        className="
          flex
          flex-col

          lg:flex-row
          lg:items-center
          lg:justify-between

          gap-4

          mb-8
        "
      >
        <div
          className="
            flex
            items-center
            gap-4
          "
        >
          <div
            className="
              w-12
              h-12

              rounded-xl

              bg-[#0D1B3E]
              text-white

              flex
              items-center
              justify-center

              shadow-md
            "
          >
            <FiUsers
              className="
                w-6
                h-6
              "
            />
          </div>


          <div>
            <h1
              className="
                text-2xl
                md:text-3xl

                font-bold

                text-[#0D1B3E]
              "
            >
              {tr(
                'enrollments.title',
                'Enrollments',
                'ការចុះឈ្មោះសិក្សា'
              )}
            </h1>


            <p
              className="
                text-sm
                text-[#6B8AFF]

                mt-0.5
              "
            >
              {tr(
                'enrollments.subtitle',
                'Manage student course enrollments',
                'គ្រប់គ្រងការចុះឈ្មោះវគ្គសិក្សារបស់សិស្ស'
              )}
            </p>
          </div>
        </div>


        <button
          type="button"

          onClick={
            fetchEnrollments
          }

          className="
            inline-flex
            items-center
            justify-center
            gap-2

            h-11
            px-5

            rounded-lg

            bg-white
            text-[#0D1B3E]

            font-semibold

            hover:bg-gray-50

            transition-all
            duration-200

            shadow-sm
            border
            border-[#E8EEF9]
          "
        >
          <FiRefreshCw
            className="
              w-4
              h-4
            "
          />

          {tr(
            'enrollments.refresh',
            'Refresh',
            'ធ្វើឱ្យថ្មី'
          )}
        </button>
      </div>


      {/* ==================================
          ERROR
      ================================== */}

      {
        error && (
          <div
            className="
              mb-6

              px-4
              py-3

              bg-[#FFEBEE]

              border
              border-[#FFCDD2]

              rounded-xl

              text-[#C62828]
              text-sm
            "
          >
            {error}
          </div>
        )
      }


      {/* ==================================
          STATS
      ================================== */}

      <div
        className="
          grid
          grid-cols-2

          xl:grid-cols-4

          gap-5

          mb-8
        "
      >
        <StatCard
          title={
            tr(
              'enrollments.totalEnrollments',
              'Total Enrollments',
              'ការចុះឈ្មោះសរុប'
            )
          }

          value={
            totalCount
          }
        />


        <StatCard
          title={
            tr(
              'enrollments.pending',
              'Pending',
              'កំពុងរង់ចាំ'
            )
          }

          value={
            pendingCount
          }
        />


        <StatCard
          title={
            tr(
              'enrollments.approved',
              'Approved',
              'បានអនុម័ត'
            )
          }

          value={
            approvedCount
          }
        />


        <StatCard
          title={
            tr(
              'enrollments.completed',
              'Completed',
              'បានបញ្ចប់'
            )
          }

          value={
            completedCount
          }
        />
      </div>


      {/* ==================================
          SEARCH
      ================================== */}

      <div
        className="
          bg-white

          border
          border-[#F0F4FB]

          rounded-xl

          shadow-sm

          p-4

          mb-6
        "
      >
        <div
          className="
            relative

            max-w-xl
          "
        >
          <FiSearch
            className="
              absolute

              left-4
              top-1/2

              -translate-y-1/2

              w-5
              h-5

              text-[#6B8AFF]
            "
          />


          <input
            type="text"

            value={
              search
            }

            onChange={
              (event) =>
                setSearch(
                  event.target.value
                )
            }

            placeholder={
              tr(
                'enrollments.searchPlaceholder',
                'Search enrollments...',
                'ស្វែងរកការចុះឈ្មោះ...'
              )
            }

            className="
              w-full

              pl-12
              pr-10

              py-3

              border
              border-[#E8EEF9]

              rounded-lg

              bg-white

              text-[#0D1B3E]

              placeholder:text-[#6B8AFF]

              focus:outline-none
              focus:border-[#0D1B3E]
              focus:ring-1
              focus:ring-[#0D1B3E]

              transition-all
              duration-200
            "
          />


          {
            search && (
              <button
                type="button"

                onClick={() =>
                  setSearch('')
                }

                className="
                  absolute

                  right-3
                  top-1/2

                  -translate-y-1/2

                  w-8
                  h-8

                  flex
                  items-center
                  justify-center

                  rounded-lg

                  text-[#6B8AFF]

                  hover:text-[#C62828]
                  hover:bg-[#FFEBEE]

                  transition-colors
                "
              >
                <FiX
                  className="
                    w-4
                    h-4
                  "
                />
              </button>
            )
          }
        </div>
      </div>


      {/* ==================================
          TABLE
      ================================== */}

      <div
        className="
          bg-white

          border
          border-[#F0F4FB]

          rounded-xl

          shadow-sm

          overflow-hidden
        "
      >
        <div
          className="
            overflow-x-auto
          "
        >
          <table
            className="
              w-full
              min-w-[1000px]
            "
          >
            <thead
              className="
                border-b
                border-[#E8EEF9]
              "
            >
              <tr>
                <TableHead>
                  #
                </TableHead>


                <TableHead>
                  {tr(
                    'enrollments.student',
                    'Student',
                    'សិស្ស'
                  )}
                </TableHead>


                <TableHead>
                  {tr(
                    'enrollments.contact',
                    'Contact',
                    'ទំនាក់ទំនង'
                  )}
                </TableHead>


                <TableHead>
                  {tr(
                    'enrollments.course',
                    'Course',
                    'វគ្គសិក្សា'
                  )}
                </TableHead>


                <TableHead>
                  {tr(
                    'enrollments.status',
                    'Status',
                    'ស្ថានភាព'
                  )}
                </TableHead>


                <TableHead>
                  {tr(
                    'enrollments.date',
                    'Date',
                    'កាលបរិច្ឆេទ'
                  )}
                </TableHead>


                <TableHead>
                  {tr(
                    'enrollments.actions',
                    'Actions',
                    'សកម្មភាព'
                  )}
                </TableHead>
              </tr>
            </thead>


            <tbody
              className="
                divide-y
                divide-[#F0F4FB]
              "
            >
              {
                filteredEnrollments
                  .length === 0
                  ? (
                    <tr>
                      <td
                        colSpan="7"

                        className="
                          px-6
                          py-16

                          text-center
                        "
                      >
                        <FiUsers
                          className="
                            w-12
                            h-12

                            mx-auto

                            text-[#E8EEF9]

                            mb-3
                          "
                        />


                        <p
                          className="
                            font-semibold
                            text-[#0D1B3E]
                          "
                        >
                          {tr(
                            'enrollments.noEnrollments',
                            'No enrollments found',
                            'មិនមានការចុះឈ្មោះ'
                          )}
                        </p>


                        <p
                          className="
                            text-sm
                            text-[#6B8AFF]

                            mt-1
                          "
                        >
                          {tr(
                            'enrollments.noEnrollmentsDescription',
                            'No student enrollments are available.',
                            'មិនទាន់មានសិស្សចុះឈ្មោះវគ្គសិក្សានៅឡើយទេ។'
                          )}
                        </p>
                      </td>
                    </tr>
                  )
                  : (
                    filteredEnrollments.map(
                      (
                        enrollment,
                        index
                      ) => {
                        const status =
                          String(
                            enrollment.status ||
                            'pending'
                          )
                            .toLowerCase()
                            .trim();


                        return (
                          <tr
                            key={
                              enrollment.id
                            }

                            className="
                              hover:bg-[#F0F7FF]/50

                              transition-colors
                              duration-150
                            "
                          >

                            {/* NUMBER */}

                            <td
                              className="
                                px-5
                                py-4

                                text-sm
                                text-[#6B8AFF]
                              "
                            >
                              {index + 1}
                            </td>


                            {/* STUDENT */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  items-center
                                  gap-3
                                "
                              >
                                <div
                                  className="
                                    w-10
                                    h-10

                                    rounded-xl

                                    bg-[#F0F7FF]

                                    flex
                                    items-center
                                    justify-center

                                    flex-shrink-0
                                  "
                                >
                                  <FiUsers
                                    className="
                                      w-5
                                      h-5

                                      text-[#0D1B3E]
                                    "
                                  />
                                </div>


                                <div>
                                  <p
                                    className="
                                      font-semibold
                                      text-[#0D1B3E]
                                    "
                                  >
                                    {
                                      enrollment.khmer_name ||
                                      enrollment.english_name ||
                                      '-'
                                    }
                                  </p>


                                  <p
                                    className="
                                      text-xs
                                      text-[#6B8AFF]

                                      mt-0.5
                                    "
                                  >
                                    ID #{enrollment.id}
                                  </p>
                                </div>
                              </div>
                            </td>


                            {/* CONTACT */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  space-y-1.5
                                "
                              >
                                <div
                                  className="
                                    flex
                                    items-center
                                    gap-2

                                    text-sm
                                    text-[#0D1B3E]
                                  "
                                >
                                  <FiMail
                                    className="
                                      w-4
                                      h-4

                                      text-[#6B8AFF]
                                    "
                                  />

                                  <span>
                                    {
                                      enrollment.email ||
                                      '-'
                                    }
                                  </span>
                                </div>


                                <div
                                  className="
                                    flex
                                    items-center
                                    gap-2

                                    text-sm
                                    text-[#0D1B3E]
                                  "
                                >
                                  <FiPhone
                                    className="
                                      w-4
                                      h-4

                                      text-[#2E7D32]
                                    "
                                  />

                                  <span>
                                    {
                                      enrollment.phone ||
                                      '-'
                                    }
                                  </span>
                                </div>
                              </div>
                            </td>


                            {/* COURSE */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  items-start
                                  gap-2
                                "
                              >
                                <FiBookOpen
                                  className="
                                    w-4
                                    h-4

                                    mt-1

                                    text-[#0D1B3E]

                                    flex-shrink-0
                                  "
                                />


                                <div>
                                  <p
                                    className="
                                      text-sm
                                      font-semibold
                                      text-[#0D1B3E]
                                    "
                                  >
                                    {
                                      getCourseName(
                                        enrollment
                                      )
                                    }
                                  </p>


                                  <p
                                    className="
                                      text-xs
                                      text-[#6B8AFF]

                                      mt-0.5
                                    "
                                  >
                                    {tr(
                                      'enrollments.courseId',
                                      'Course ID',
                                      'លេខសម្គាល់វគ្គ'
                                    )}:{' '}

                                    {
                                      enrollment.course_id ||
                                      '-'
                                    }
                                  </p>
                                </div>
                              </div>
                            </td>


                            {/* STATUS */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  flex-col
                                  gap-2
                                "
                              >
                                <span
                                  className={`
                                    inline-flex
                                    items-center
                                    justify-center

                                    w-fit

                                    px-3
                                    py-1

                                    rounded-full

                                    text-xs
                                    font-semibold

                                    ${getStatusStyle(
                                      status
                                    )}
                                  `}
                                >
                                  {
                                    getStatusLabel(
                                      status
                                    )
                                  }
                                </span>


                                <select
                                  value={
                                    status
                                  }

                                  disabled={
                                    updatingId ===
                                    enrollment.id
                                  }

                                  onChange={
                                    (event) =>
                                      handleStatusChange(
                                        enrollment,
                                        event.target.value
                                      )
                                  }

                                  className="
                                    min-w-[140px]

                                    px-3
                                    py-2

                                    border
                                    border-[#E8EEF9]

                                    rounded-lg

                                    bg-white

                                    text-sm
                                    text-[#0D1B3E]

                                    focus:outline-none
                                    focus:border-[#0D1B3E]
                                    focus:ring-1
                                    focus:ring-[#0D1B3E]

                                    disabled:opacity-50
                                    disabled:cursor-not-allowed
                                  "
                                >
                                  {
                                    STATUS_OPTIONS.map(
                                      (
                                        option
                                      ) => (
                                        <option
                                          key={
                                            option
                                          }

                                          value={
                                            option
                                          }
                                        >
                                          {
                                            getStatusLabel(
                                              option
                                            )
                                          }
                                        </option>
                                      )
                                    )
                                  }
                                </select>
                              </div>
                            </td>


                            {/* DATE */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  items-start
                                  gap-2

                                  text-sm
                                  text-[#0D1B3E]
                                "
                              >
                                <FiCalendar
                                  className="
                                    w-4
                                    h-4

                                    mt-0.5

                                    text-[#6B8AFF]

                                    flex-shrink-0
                                  "
                                />


                                <span>
                                  {
                                    formatDate(
                                      enrollment.created_at,
                                      language
                                    )
                                  }
                                </span>
                              </div>
                            </td>


                            {/* ACTIONS */}

                            <td
                              className="
                                px-5
                                py-4
                              "
                            >
                              <div
                                className="
                                  flex
                                  items-center
                                  gap-2
                                "
                              >
                                <button
                                  type="button"

                                  title={
                                    tr(
                                      'enrollments.viewDetails',
                                      'View Details',
                                      'មើលព័ត៌មានលម្អិត'
                                    )
                                  }

                                  onClick={() =>
                                    setSelectedEnrollment(
                                      enrollment
                                    )
                                  }

                                  className="
                                    w-8
                                    h-8

                                    rounded-lg

                                    bg-[#F0F7FF]
                                    text-[#0D1B3E]

                                    flex
                                    items-center
                                    justify-center

                                    hover:bg-[#0D1B3E]
                                    hover:text-white

                                    transition-all
                                    duration-200
                                  "
                                >
                                  <FiEye
                                    className="
                                      w-4
                                      h-4
                                    "
                                  />
                                </button>


                                <button
                                  type="button"

                                  title={
                                    tr(
                                      'common.delete',
                                      'Delete',
                                      'លុប'
                                    )
                                  }

                                  disabled={
                                    deletingId ===
                                    enrollment.id
                                  }

                                  onClick={() =>
                                    handleDelete(
                                      enrollment
                                    )
                                  }

                                  className="
                                    w-8
                                    h-8

                                    rounded-lg

                                    bg-[#FFEBEE]
                                    text-[#C62828]

                                    flex
                                    items-center
                                    justify-center

                                    hover:bg-[#C62828]
                                    hover:text-white

                                    transition-all
                                    duration-200

                                    disabled:opacity-50
                                    disabled:cursor-not-allowed
                                  "
                                >
                                  {
                                    deletingId ===
                                    enrollment.id
                                      ? (
                                        <FiRefreshCw
                                          className="
                                            w-4
                                            h-4

                                            animate-spin
                                          "
                                        />
                                      )
                                      : (
                                        <FiTrash2
                                          className="
                                            w-4
                                            h-4
                                          "
                                        />
                                      )
                                  }
                                </button>
                              </div>
                            </td>
                          </tr>
                        );
                      }
                    )
                  )
              }
            </tbody>
          </table>
        </div>
      </div>


      {/* ==================================
          VIEW MODAL
      ================================== */}

      {
        selectedEnrollment && (
          <div
            className="
              fixed
              inset-0

              z-50

              flex
              items-center
              justify-center

              bg-black/50

              p-4
            "
          >
            <div
              className={`
                bg-white

                w-full
                max-w-2xl

                max-h-[90vh]

                overflow-y-auto

                rounded-2xl

                shadow-2xl

                ${
                  isKhmer
                    ? 'font-khmer'
                    : 'font-english'
                }
              `}
            >

              {/* MODAL HEADER */}

              <div
                className="
                  flex
                  items-center
                  justify-between

                  gap-4

                  px-6
                  py-5

                  bg-[#0D1B3E]

                  rounded-t-2xl
                "
              >
                <div
                  className="
                    flex
                    items-center
                    gap-3
                  "
                >
                  <div
                    className="
                      w-10
                      h-10

                      rounded-xl

                      bg-white/10

                      flex
                      items-center
                      justify-center
                    "
                  >
                    <FiUsers
                      className="
                        w-5
                        h-5

                        text-white
                      "
                    />
                  </div>


                  <div>
                    <h2
                      className="
                        text-lg
                        sm:text-xl

                        font-bold
                        text-white
                      "
                    >
                      {tr(
                        'enrollments.enrollmentDetails',
                        'Enrollment Details',
                        'ព័ត៌មានលម្អិតនៃការចុះឈ្មោះ'
                      )}
                    </h2>


                    <p
                      className="
                        text-xs
                        text-white/60

                        mt-0.5
                      "
                    >
                      {tr(
                        'enrollments.enrollment',
                        'Enrollment',
                        'ការចុះឈ្មោះ'
                      )}{' '}

                      #{selectedEnrollment.id}
                    </p>
                  </div>
                </div>


                <button
                  type="button"

                  onClick={() =>
                    setSelectedEnrollment(
                      null
                    )
                  }

                  className="
                    w-9
                    h-9

                    rounded-lg

                    flex
                    items-center
                    justify-center

                    text-white/70

                    hover:bg-white/10
                    hover:text-white

                    transition-colors
                  "
                >
                  <FiX
                    className="
                      w-5
                      h-5
                    "
                  />
                </button>
              </div>


              {/* MODAL BODY */}

              <div
                className="
                  p-6

                  space-y-6
                "
              >
                <div
                  className="
                    grid
                    grid-cols-1
                    sm:grid-cols-2

                    gap-6
                  "
                >
                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.khmerName',
                      'Khmer Name',
                      'ឈ្មោះជាភាសាខ្មែរ'
                    )}
                    value={selectedEnrollment.khmer_name}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.englishName',
                      'English Name',
                      'ឈ្មោះជាភាសាអង់គ្លេស'
                    )}
                    value={selectedEnrollment.english_name}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.gender',
                      'Gender',
                      'ភេទ'
                    )}
                    value={selectedEnrollment.gender}
                  />

                  <DetailItem
                    icon={FiCalendar}
                    label={tr(
                      'enrollments.age',
                      'Age',
                      'អាយុ'
                    )}
                    value={selectedEnrollment.age}
                  />

                  <DetailItem
                    icon={FiCalendar}
                    label={tr(
                      'enrollments.dateOfBirth',
                      'Date of Birth',
                      'ថ្ងៃ ខែ ឆ្នាំកំណើត'
                    )}
                    value={selectedEnrollment.date_of_birth}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.nationality',
                      'Nationality',
                      'សញ្ជាតិ'
                    )}
                    value={selectedEnrollment.nationality}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.nation',
                      'Nation',
                      'ជាតិ'
                    )}
                    value={selectedEnrollment.nation}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.religion',
                      'Religion',
                      'សាសនា'
                    )}
                    value={selectedEnrollment.religion}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.stateIdNo',
                      'State ID No.',
                      'លេខអត្តសញ្ញាណប័ណ្ណ'
                    )}
                    value={selectedEnrollment.state_id_no}
                  />

                  <DetailItem
                    icon={FiCalendar}
                    label={tr(
                      'enrollments.issuedOn',
                      'Issued On',
                      'ចេញថ្ងៃទី'
                    )}
                    value={selectedEnrollment.issued_on}
                  />

                  <DetailItem
                    icon={FiCalendar}
                    label={tr(
                      'enrollments.expiredOn',
                      'Expired On',
                      'ផុតកំណត់ថ្ងៃទី'
                    )}
                    value={selectedEnrollment.expired_on}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.houseNo',
                      'House No.',
                      'លេខផ្ទះ'
                    )}
                    value={selectedEnrollment.house_no}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.village',
                      'Village',
                      'ភូមិ'
                    )}
                    value={selectedEnrollment.village}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.communeSangkat',
                      'Commune / Sangkat',
                      'ឃុំ / សង្កាត់'
                    )}
                    value={selectedEnrollment.commune_sangkat}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.districtKhan',
                      'District / Khan',
                      'ស្រុក / ខណ្ឌ'
                    )}
                    value={selectedEnrollment.district_khan}
                  />

                  <DetailItem
                    icon={FiUsers}
                    label={tr(
                      'enrollments.provinceCity',
                      'Province / City',
                      'រាជធានី / ខេត្ត'
                    )}
                    value={selectedEnrollment.province_city}
                  />

                  <DetailItem
                    icon={FiMail}
                    label={tr(
                      'enrollments.email',
                      'Email',
                      'អ៊ីមែល'
                    )}
                    value={selectedEnrollment.email}
                  />

                  <DetailItem
                    icon={FiPhone}
                    label={tr(
                      'enrollments.phone',
                      'Phone',
                      'លេខទូរស័ព្ទ'
                    )}
                    value={selectedEnrollment.phone}
                  />

                  <DetailItem
                    icon={FiBookOpen}
                    label={tr(
                      'enrollments.course',
                      'Course',
                      'វគ្គសិក្សា'
                    )}
                    value={getCourseName(selectedEnrollment)}
                  />

                  <DetailItem
                    icon={FiCalendar}
                    label={tr(
                      'enrollments.enrollmentDate',
                      'Enrollment Date',
                      'កាលបរិច្ឆេទចុះឈ្មោះ'
                    )}
                    value={formatDate(
                      selectedEnrollment.created_at,
                      language
                    )}
                  />

                  <div>
                    <p
                      className="
                        text-sm
                        font-medium
                        text-[#6B8AFF]
                        mb-2
                      "
                    >
                      {tr(
                        'enrollments.status',
                        'Status',
                        'ស្ថានភាព'
                      )}
                    </p>

                    <select
                      value={String(
                        selectedEnrollment.status || 'pending'
                      ).toLowerCase().trim()}
                      disabled={
                        updatingId === selectedEnrollment.id
                      }
                      onChange={(event) =>
                        handleStatusChange(
                          selectedEnrollment,
                          event.target.value
                        )
                      }
                      className="
                        w-full
                        px-3
                        py-2.5
                        border
                        border-[#E8EEF9]
                        rounded-xl
                        bg-white
                        text-[#0D1B3E]
                        focus:outline-none
                        focus:border-[#0D1B3E]
                        focus:ring-1
                        focus:ring-[#0D1B3E]
                        disabled:opacity-50
                        disabled:cursor-not-allowed
                      "
                    >
                      {STATUS_OPTIONS.map((option) => (
                        <option key={option} value={option}>
                          {getStatusLabel(option)}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

              </div>


              {/* MODAL FOOTER */}

              <div
                className="
                  flex
                  flex-col-reverse
                  sm:flex-row

                  justify-end

                  gap-3

                  px-6
                  py-4

                  border-t
                  border-[#E8EEF9]
                "
              >
                <button
                  type="button"

                  onClick={() =>
                    setSelectedEnrollment(
                      null
                    )
                  }

                  className="
                    px-5
                    py-2.5

                    border
                    border-[#E8EEF9]

                    rounded-xl

                    text-[#6B8AFF]

                    font-semibold

                    hover:bg-[#F0F7FF]

                    transition-colors
                  "
                >
                  {tr(
                    'common.close',
                    'Close',
                    'បិទ'
                  )}
                </button>


                <button
                  type="button"

                  disabled={
                    deletingId ===
                    selectedEnrollment.id
                  }

                  onClick={() =>
                    handleDelete(
                      selectedEnrollment
                    )
                  }

                  className="
                    inline-flex
                    items-center
                    justify-center
                    gap-2

                    px-5
                    py-2.5

                    bg-[#C23636]
                    text-white

                    rounded-xl

                    font-semibold

                    hover:bg-[#A92E2E]

                    transition-colors

                    disabled:opacity-50
                    disabled:cursor-not-allowed
                  "
                >
                  {
                    deletingId ===
                    selectedEnrollment.id
                      ? (
                        <>
                          <FiRefreshCw
                            className="
                              w-4
                              h-4

                              animate-spin
                            "
                          />

                          {tr(
                            'enrollments.deleting',
                            'Deleting...',
                            'កំពុងលុប...'
                          )}
                        </>
                      )
                      : (
                        <>
                          <FiTrash2
                            className="
                              w-4
                              h-4
                            "
                          />

                          {tr(
                            'common.delete',
                            'Delete',
                            'លុប'
                          )}
                        </>
                      )
                  }
                </button>
              </div>
            </div>
          </div>
        )
      }
    </div>
  );
};


// ==========================================
// STAT CARD
// ==========================================

const StatCard = ({
  title,
  value,
}) => {
  return (
    <div
      className="
        bg-white

        border
        border-[#F0F4FB]

        rounded-xl

        p-5

        shadow-sm
      "
    >
      <p
        className="
          text-sm
          text-[#6B8AFF]
        "
      >
        {title}
      </p>


      <p
        className="
          text-2xl
          font-bold
          text-[#0D1B3E]

          mt-1
        "
      >
        {value}
      </p>
    </div>
  );
};


// ==========================================
// TABLE HEAD
// ==========================================

const TableHead = ({
  children,
}) => {
  return (
    <th
      className="
        px-5
        py-4

        text-left

        text-xs
        font-bold

        uppercase
        tracking-wider

        text-[#6B8AFF]

        whitespace-nowrap
      "
    >
      {children}
    </th>
  );
};


// ==========================================
// DETAIL ITEM
// ==========================================

const DetailItem = ({
  icon: Icon,
  label,
  value,
}) => {
  return (
    <div
      className="
        flex
        items-start
        gap-4
      "
    >
      <div
        className="
          w-10
          h-10

          rounded-xl

          bg-[#F0F7FF]

          flex
          items-center
          justify-center

          flex-shrink-0
        "
      >
        <Icon
          className="
            w-5
            h-5

            text-[#0D1B3E]
          "
        />
      </div>


      <div
        className="
          min-w-0
        "
      >
        <p
          className="
            text-sm
            text-[#6B8AFF]
          "
        >
          {label}
        </p>


        <p
          className="
            text-[#0D1B3E]
            font-medium

            mt-1

            break-words
          "
        >
          {value || '-'}
        </p>
      </div>
    </div>
  );
};


export default AdminEnrollments;
